public class PlayerAttack : MonoBehaviour
{
    public static Transform targetMonster;
    public WeaponType weaponType;
    public float targetRange = 50f;
    public float targetAngle = 60f;

    void Update()
    {
        if (Input.GetMouseButtonDown(0))
        {
            Attack();
        }

        if (Input.GetKeyDown(KeyCode.Tab))
        {
            FindClosestMonster();
        }
    }

    public Transform FindClosestMonster()
    {
        GameObject[] monsters = GameObject.FindGameObjectsWithTag("Monster");
        Transform closestMonster = null;
        float closestDistance = targetRange;

        foreach (GameObject monster in monsters)
        {
            float distance = Vector3.Distance(transform.position, monster.transform.position);
            Vector3 direction = (monster.transform.position - transform.position).normalized;
            float angle = Vector3.Angle(transform.forward, direction);

            if (distance < closestDistance && angle < targetAngle / 2)
            {
                closestDistance = distance;
                closestMonster = monster.transform;
            }
        }

        targetMonster = closestMonster;
        return closestMonster;
    }

    void Attack()
    {
        switch (weaponType)
        {
            case WeaponType.BOW:
                FireArrow();
                break;
            case WeaponType.GUN:
                FireBullet();
                break;
            case WeaponType.AURAS:
                FireMagicArrow();
                break;
        }
    }
}

