public class LastBossAction : MonoBehaviour
{
    public enum BossPhase { Phase1, Phase2, Phase3 }
    public BossPhase currentPhase = BossPhase.Phase1;

    public float[] phaseHPThresholds = { 100f, 60f, 30f };
    private float currentHP = 100f;

    void Update()
    {
        UpdatePhase();
        ExecutePhasePattern();
    }

    void UpdatePhase()
    {
        if (currentHP <= phaseHPThresholds[2] && currentPhase != BossPhase.Phase3)
        {
            currentPhase = BossPhase.Phase3;
            StartPhase3();
        }
        else if (currentHP <= phaseHPThresholds[1] && currentPhase == BossPhase.Phase1)
        {
            currentPhase = BossPhase.Phase2;
            StartPhase2();
        }
    }

    void ExecutePhasePattern()
    {
        switch (currentPhase)
        {
            case BossPhase.Phase1:
                // 기본 공격 패턴
                if (Random.Range(0f, 1f) < 0.3f)
                    StartCoroutine(GroundPoundAttack());
                break;

            case BossPhase.Phase2:
                // 도끼 투척 패턴 추가
                if (Random.Range(0f, 1f) < 0.4f)
                    StartCoroutine(FlyAxeAttack());
                break;

            case BossPhase.Phase3:
                // 픽셀화 공격 및 화염 베기
                if (Random.Range(0f, 1f) < 0.5f)
                    StartCoroutine(PixelateAttack());
                break;
        }
    }

    IEnumerator PixelateAttack()
    {
        // 화면 픽셀화 효과 시작
        FindObjectOfType<LastBossPixelate>().StartPixelateEffect();

        yield return new WaitForSeconds(2f);

        // 플레이어에게 데미지
        // 픽셀화 효과 종료
    }
}

