public class SaveSystem : MonoBehaviour
{
    private string connectionString = "Server=localhost;Database=GameDB;";

    public async void SavePlayerData(PlayerState playerState)
    {
        try
        {
            using (MySqlConnection connection = new MySqlConnection(connectionString))
            {
                await connection.OpenAsync();

                string query = @"UPDATE Players SET 
                               Level = @level, HP = @hp, Money = @money, 
                               Exp = @exp, BulletCount = @bulletCount, 
                               PlayTime = @playTime, Kills = @kills 
                               WHERE PlayerID = @playerID";

                using (MySqlCommand command = new MySqlCommand(query, connection))
                {
                    command.Parameters.AddWithValue("@level", playerState.Level);
                    command.Parameters.AddWithValue("@hp", playerState.HP);
                    // ... 다른 매개변수들

                    await command.ExecuteNonQueryAsync();
                }
            }
        }
        catch (Exception ex)
        {
            Debug.LogError($"Save failed: {ex.Message}");
        }
    }
}

