public class LevelExp : MonoBehaviour
{
    public PlayerState playerState;
    public Text levelText;
    public Text expText;
    public Slider expSlider;

    private int[] expRequirements = { 100, 250, 500, 1000, 2000 };

    void Update()
    {
        UpdateUI();
        CheckLevelUp();
    }

    void CheckLevelUp()
    {
        if (playerState.Level < expRequirements.Length)
        {
            int requiredExp = expRequirements[playerState.Level - 1];

            if (playerState.exp >= requiredExp)
            {
                LevelUp();
            }
        }
    }

    void LevelUp()
    {
        playerState.Level++;
        playerState.exp -= expRequirements[playerState.Level - 2];

        // 능력치 증가
        playerState.HP += 20;

        // 레벨업 효과
        ShowLevelUpEffect();

        Debug.Log($"레벨업! 현재 레벨: {playerState.Level}");
    }

    void UpdateUI()
    {
        levelText.text = $"Level: {playerState.Level}";

        if (playerState.Level < expRequirements.Length)
        {
            int requiredExp = expRequirements[playerState.Level - 1];
            expText.text = $"EXP: {playerState.exp}/{requiredExp}";
            expSlider.value = (float)playerState.exp / requiredExp;
        }
        else
        {
            expText.text = "MAX LEVEL";
            expSlider.value = 1f;
        }
    }

    public void GainExperience(int amount)
    {
        playerState.exp += amount;

        // 경험치 획득 애니메이션
        StartCoroutine(ShowExpGainAnimation(amount));
    }
}

