public class PlayerAurasArrow : MonoBehaviour
{
    public ParticleSystem magicTrail;
    public Material aurasShader;
    public Transform target;

    void Start()
    {
        // 마법 화살 셰이더 효과 적용
        GetComponent<Renderer>().material = aurasShader;

        // 파티클 트레일 시작
        magicTrail.Play();

        // 타겟을 향한 이동
        if (PlayerAttack.targetMonster != null)
        {
            target = PlayerAttack.targetMonster;
            StartCoroutine(MoveToTarget());
        }
    }

    IEnumerator MoveToTarget()
    {
        float speed = 15f;

        while (target != null && Vector3.Distance(transform.position, target.position) > 0.5f)
        {
            Vector3 direction = (target.position - transform.position).normalized;
            transform.position += direction * speed * Time.deltaTime;

            // 회전 효과
            transform.Rotate(0, 0, 360 * Time.deltaTime);

            yield return null;
        }

        // 충돌 효과
        CreateImpactEffect();

        Destroy(gameObject);
    }

    void CreateImpactEffect()
    {
        // 충돌 파티클 생성
        GameObject impactEffect = Instantiate(impactParticlePrefab, transform.position, Quaternion.identity);
        Destroy(impactEffect, 2f);
    }
}

public class LastBossPixelate : MonoBehaviour
{
    public Material pixelateMaterial;
    public Camera mainCamera;

    public void StartPixelateEffect()
    {
        StartCoroutine(PixelateSequence());
    }

    IEnumerator PixelateSequence()
    {
        // 화면을 점진적으로 픽셀화
        for (float pixelSize = 1f; pixelSize <= 64f; pixelSize += 2f)
        {
            pixelateMaterial.SetFloat("_PixelSize", pixelSize);
            yield return new WaitForSeconds(0.1f);
        }

        // 2초간 유지
        yield return new WaitForSeconds(2f);

        // 원상복구
        for (float pixelSize = 64f; pixelSize >= 1f; pixelSize -= 2f)
        {
            pixelateMaterial.SetFloat("_PixelSize", pixelSize);
            yield return new WaitForSeconds(0.05f);
        }
    }
}

