public class BackgroundBGM : MonoBehaviour
{
    public AudioSource bgmSource;
    public AudioClip[] sceneMusics;
    private GameManager gameManager;

    void Start()
    {
        gameManager = GameManager.info;
        UpdateBGMVolume();
        PlaySceneMusic();
    }

    void Update()
    {
        // 게임 매니저에서 볼륨 설정 확인
        if (bgmSource.volume != gameManager.musicVolume)
        {
            UpdateBGMVolume();
        }
    }

    void UpdateBGMVolume()
    {
        bgmSource.volume = gameManager.musicVolume;
    }

    void PlaySceneMusic()
    {
        string currentScene = SceneManager.GetActiveScene().name;

        switch (currentScene)
        {
            case "Village":
                bgmSource.clip = sceneMusics[0];
                break;
            case "Forest":
                bgmSource.clip = sceneMusics[1];
                break;
            case "Desert":
                bgmSource.clip = sceneMusics[2];
                break;
            case "BossRoom":
                bgmSource.clip = sceneMusics[3];
                break;
        }

        if (!bgmSource.isPlaying)
            bgmSource.Play();
    }
}

