public class PlayerTeleport : MonoBehaviour
{
    public string targetSceneName;
    public Vector3 targetPosition;
    public bool requiresLoading = true;

    void OnTriggerEnter(Collider other)
    {
        if (other.CompareTag("Player"))
        {
            StartCoroutine(TeleportSequence());
        }
    }

    IEnumerator TeleportSequence()
    {
        if (requiresLoading)
        {
            // 로딩 화면 표시
            Loading.Instance.ShowLoading();
        }

        // 페이드 아웃
        FadeInOutEffect fadeEffect = FindObjectOfType<FadeInOutEffect>();
        if (fadeEffect != null)
        {
            yield return StartCoroutine(fadeEffect.FadeOut());
        }

        // 플레이어 위치 저장
        GameManager.info.SetPlayerPosition(targetPosition);

        // 씬 로드
        AsyncOperation asyncLoad = SceneManager.LoadSceneAsync(targetSceneName);

        while (!asyncLoad.isDone)
        {
            // 로딩 진행률 업데이트
            if (Loading.Instance != null)
            {
                Loading.Instance.UpdateProgress(asyncLoad.progress);
            }
            yield return null;
        }
    }
}

public class Loading : MonoBehaviour
{
    public static Loading Instance;
    public GameObject loadingUI;
    public Slider progressSlider;
    public Text progressText;

    void Awake()
    {
        if (Instance == null)
        {
            Instance = this;
            DontDestroyOnLoad(gameObject);
        }
        else
        {
            Destroy(gameObject);
        }
    }

    public void ShowLoading()
    {
        loadingUI.SetActive(true);
        progressSlider.value = 0f;
        progressText.text = "0%";
    }

    public void UpdateProgress(float progress)
    {
        progressSlider.value = progress;
        progressText.text = $"{(int)(progress * 100)}%";
    }

    public void HideLoading()
    {
        loadingUI.SetActive(false);
    }
}
